command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="2d38f480998e522e4cfbe2b8a3ca2fef68ff6637"
$candidate="b414e8e3f8eb5e6c771c1f41ba4e632c143b1db4"
$branch="work/removable-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "docs policy fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before docs policy validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "docs policy candidate ref mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){
  $dirty | ForEach-Object { Write-Host ("UNEXPECTED_WORKTREE="+$_) }
  throw "persistent checkout is not clean before docs policy validation"
}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "docs policy candidate checkout failed"}
& .\test.bat policy
if($LASTEXITCODE -ne 0){throw "policy gate failed"}
& git diff --check $main $candidate
if($LASTEXITCODE -ne 0){throw "git diff --check failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore canonical main checkout"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward canonical main checkout"}
Write-Host "REMOVABLE_SHELL_VISUAL_DOCS_POLICY=PASS"
